'use strict';

// MODULES //

var tape = require( 'tape' );
var insert = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof insert, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an empty tokens array (cannot insert at root)', function test( t ) {
	var doc;

	doc = [ 1, 2 ];
	t.throws( badValue, Error, 'throws an error when provided empty tokens' );
	t.end();

	function badValue() {
		insert( doc, [], 99 );
	}
});

tape( 'the function immutably inserts a value at the beginning of an array', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = [ 1, 2, 3 ];
	expected = [ 99, 1, 2, 3 ];

	out = insert( doc, [ '0' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function immutably inserts a value into the middle of an array', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = [ 1, 2, 3 ];
	expected = [ 1, 99, 2, 3 ];

	out = insert( doc, [ '1' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function immutably appends a value to an array when provided the `-` token', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = [ 1, 2, 3 ];
	expected = [ 1, 2, 3, 99 ];

	out = insert( doc, [ '-' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function immutably inserts a value into a nested array', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': {
			'b': [ 1, 2, 3 ]
		}
	};
	expected = {
		'a': {
			'b': [ 1, 99, 2, 3 ]
		}
	};

	out = insert( doc, [ 'a', 'b', '1' ], 99 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );
	t.notEqual( out.a.b, doc.a.b, 'returns expected value' );

	t.end();
});

tape( 'the function uses structural sharing for unchanged subtrees', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': {
			'b': [ 1, 2, 3 ]
		},
		'c': {
			'd': 42
		}
	};
	out = insert( doc, [ 'a', 'b', '1' ], 99 );

	t.strictEqual( out.c, doc.c, 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );

	t.end();
});

tape( 'the function throws a type error if the target container is not an array', function test( t ) {
	var doc;

	doc = {
		'a': {
			'b': 1
		}
	};
	t.throws( badValue, TypeError, 'throws a type error when target is an object' );
	t.end();

	function badValue() {
		insert( doc, [ 'a', 'b' ], 99 );
	}
});

tape( 'the function throws a range error if the array index is out of bounds', function test( t ) {
	var values;
	var doc;
	var i;

	doc = [ 1, 2, 3 ];
	values = [
		'4',
		'10'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			insert( doc, [ value ], 99 );
		};
	}
});

tape( 'the function throws an error if a token is an unsafe value (prototype pollution vector)', function test( t ) {
	var values;
	var i;

	values = [
		'__proto__',
		'constructor',
		'prototype'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			insert( [ 1, 2 ], [ value ], 99 );
		};
	}
});

tape( 'the function throws a type error if an intermediate path segment references a non-traversable value', function test( t ) {
	var values;
	var i;

	values = [
		'',
		42,
		true,
		null
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws when provided ' + ( typeof values[ i ] ) );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			insert({
				'a': value
			}, [ 'a', '0' ], 99 );
		};
	}
});

tape( 'the function does not mutate the original document', function test( t ) {
	var doc;
	var out;

	doc = [ 1, 2, 3 ];
	out = insert( doc, [ '1' ], 99 );

	t.deepEqual( doc, [ 1, 2, 3 ], 'returns expected value' );
	t.deepEqual( out, [ 1, 99, 2, 3 ], 'returns expected value' );

	t.end();
});
